"use client";

import type { Colorway } from "./sneaker";

type Props = {
  colorway: Colorway["id"];
  onPick: (id: Colorway["id"]) => void;
};

const SWATCHES: {
  id: Colorway["id"];
  en: string;
  ko: string;
  hex: string;
  blurbEn: string;
  blurbKo: string;
}[] = [
  {
    id: "ember",
    en: "Ember",
    ko: "엠버",
    hex: "#ff5722",
    blurbEn: "Heat-treated suede and a molten accent. The studio's default.",
    blurbKo: "열처리 스웨이드와 녹아내린 액센트. 스튜디오의 기본값.",
  },
  {
    id: "ocean",
    en: "Ocean",
    ko: "오션",
    hex: "#0066ff",
    blurbEn: "Deep navy knit, electric trim. Reads cool under the rim light.",
    blurbKo: "짙은 네이비 니트, 전기빛 띠. 림 라이트 아래서 차갑게 읽힌다.",
  },
  {
    id: "frost",
    en: "Frost",
    ko: "프로스트",
    hex: "#e8eef5",
    blurbEn: "Bone-white upper on a clean sole. The lightest object in the room.",
    blurbKo: "뼈빛 어퍼에 맑은 솔. 방 안에서 가장 가벼운 물건.",
  },
];

/**
 * Section 03 — the colorway. Three panels wipe in with direction-aware
 * clip-path insets (clip-path-reveal), 640ms ease-out-settle, 90ms stagger.
 * The selected swatch is a real radio-style control group (keyboard
 * reachable, focus-visible art-directed); picking one updates the turntable
 * above via the parent's state.
 *
 * Each panel's wipe direction rotates (right, up, left) so the grid doesn't
 * read as a synchronized slab. The pre-wipe state is gated behind
 * `.orbit-js` (added on mount) so without JavaScript every panel is simply
 * visible.
 */
export default function ColorwayPicker({ colorway, onPick }: Props) {
  return (
    <section className="orbit-colorway" aria-labelledby="orbit-colorway-title">
      <div className="orbit-section__head" data-reveal>
        <p className="orbit-section__no" aria-hidden="true">
          03 · COLORWAY
        </p>
        <h2 className="orbit-section__title" id="orbit-colorway-title">
          Pick a finish{" "}
          <span lang="ko" className="orbit-section__ko">
            컬러웨이
          </span>
        </h2>
        <p className="orbit-section__meta">
          THREE DROPS · <span lang="ko">세 가지 마감</span>
        </p>
      </div>

      <div className="orbit-colorway__grid" role="radiogroup" aria-label="Colorway · 컬러웨이">
        {SWATCHES.map((s, i) => {
          const selected = s.id === colorway;
          const dir = i % 3; // 0=from-right, 1=from-bottom, 2=from-left
          return (
            <button
              type="button"
              key={s.id}
              role="radio"
              aria-checked={selected}
              data-reveal-wipe={dir}
              className={`orbit-colorway__panel${
                selected ? " is-selected" : ""
              }`}
              onClick={() => onPick(s.id)}
              style={{ "--orbit-wipe-delay": `${i * 90}ms` } as React.CSSProperties}
            >
              <span className="orbit-colorway__swatch" aria-hidden="true">
                <span
                  className="orbit-colorway__swatch-dot"
                  style={{ background: s.hex }}
                />
                <span className="orbit-colorway__swatch-ring" />
              </span>
              <span className="orbit-colorway__name">
                <span className="orbit-colorway__name-en">{s.en}</span>
                <span className="orbit-colorway__name-ko" lang="ko">
                  {s.ko}
                </span>
              </span>
              <span className="orbit-colorway__blurb">{s.blurbEn}</span>
              <span className="orbit-colorway__blurb orbit-colorway__blurb--ko" lang="ko">
                {s.blurbKo}
              </span>
              <span className="orbit-colorway__hex" aria-hidden="true">
                {s.hex.toUpperCase()}
              </span>
            </button>
          );
        })}
      </div>
    </section>
  );
}

"use client";

import { useRef } from "react";
import { useScrollProgress } from "../hooks/useScrollProgress";
import { withAlpha } from "./sneaker";

/**
 * Section 02 — the build, pinned and scrubbed. As you scroll through the
 * 220vh pin, the silhouette's parts separate vertically into an exploded
 * technical illustration, connected by hairline rails and labeled in both
 * languages. The separation is driven by `--orbit-build` (0→1), written by
 * useScrollProgress from the pin's scroll position.
 *
 * Each part is its own absolutely-positioned SVG layer with a per-part
 * offset; the offset reads `calc(var(--orbit-build) * <partMax>px)` so the
 * further-up parts travel further — the classic exploded-diagram spread.
 * The rails are clip-path-revealed as the parts move apart, so the diagram
 * "draws itself" as you scrub.
 *
 * Under reduced motion the lerp in useScrollProgress is bypassed, so the
 * spread tracks the wheel 1:1 — still fully usable, just unsmoothed.
 */
export default function ExplodedBuild() {
  const pinRef = useRef<HTMLDivElement | null>(null);
  useScrollProgress(pinRef, "--orbit-build");

  // Part travel in px at progress=1 (desktop). Scaled down on narrow screens
  // via the CSS (the calc uses a CSS var --orbit-explode-unit that the
  // stylesheet clamps responsively).
  return (
    <section
      className="orbit-build"
      aria-labelledby="orbit-build-title"
      ref={pinRef}
    >
      <div className="orbit-build__sticky">
        <div className="orbit-build__head" data-reveal>
          <p className="orbit-section__no" aria-hidden="true">
            02 · BUILD
          </p>
          <h2 className="orbit-section__title" id="orbit-build-title">
            Take it apart{" "}
            <span lang="ko" className="orbit-section__ko">
              분해도
            </span>
          </h2>
          <p className="orbit-section__meta">
            SCROLL TO EXPLODE · <span lang="ko">스크롤하면 펼쳐진다</span>
          </p>
        </div>

        <div className="orbit-build__diagram" role="img" aria-label="Exploded build diagram of the ORBIT sneaker: from bottom to top — rubber outsole, foam midsole, knit upper with its accent stripe, the lace pack, and the heel counter. 아래부터 위로 — 고무 아웃솔, 폼 미드솔, 니트 어퍼와 액센트 띠, 레이스팩, 힐 카운터의 분해도.">
          {/* Center axis rail (drawn by clip-path as parts separate) */}
          <span className="orbit-build__rail orbit-build__rail--a" aria-hidden="true" />
          <span className="orbit-build__rail orbit-build__rail--b" aria-hidden="true" />
          <span className="orbit-build__rail orbit-build__rail--c" aria-hidden="true" />
          <span className="orbit-build__rail orbit-build__rail--d" aria-hidden="true" />

          {/* Part layers, bottom → top. Each translates up by its offset. */}
          <ExplodedPart
            cls="orbit-build__part--outsole"
            labelEn="Outsole"
            labelKo="아웃솔"
            meta="Rubber · 4.2 mm"
            metaKo="고무 · 4.2mm"
          >
            <PartOutsole />
          </ExplodedPart>

          <ExplodedPart
            cls="orbit-build__part--midsole"
            labelEn="Midsole"
            labelKo="미드솔"
            meta="PEBA foam · 14 mm"
            metaKo="PEBA 폼 · 14mm"
          >
            <PartMidsole />
          </ExplodedPart>

          <ExplodedPart
            cls="orbit-build__part--upper"
            labelEn="Upper"
            labelKo="어퍼"
            meta="Knit + saddle"
            metaKo="니트 + 새들"
          >
            <PartUpper />
          </ExplodedPart>

          <ExplodedPart
            cls="orbit-build__part--laces"
            labelEn="Lace pack"
            labelKo="레이스팩"
            meta="Waxed · 6 eyelets"
            metaKo="왁스 가공 · 구멍 6"
          >
            <PartLaces />
          </ExplodedPart>

          <ExplodedPart
            cls="orbit-build__part--counter"
            labelEn="Heel counter"
            labelKo="힐 카운터"
            meta="TPU frame"
            metaKo="TPU 프레임"
          >
            <PartCounter />
          </ExplodedPart>
        </div>
      </div>
    </section>
  );
}

type PartProps = {
  cls: string;
  labelEn: string;
  labelKo: string;
  meta: string;
  metaKo: string;
  children: React.ReactNode;
};

function ExplodedPart({ cls, labelEn, labelKo, meta, metaKo, children }: PartProps) {
  return (
    <div className={`orbit-build__part ${cls}`}>
      <div className="orbit-build__part-art" aria-hidden="true">
        {children}
      </div>
      <div className="orbit-build__part-label">
        <span className="orbit-build__part-en">{labelEn}</span>
        <span className="orbit-build__part-ko" lang="ko">
          {labelKo}
        </span>
        <span className="orbit-build__part-meta">
          {meta} · <span lang="ko">{metaKo}</span>
        </span>
      </div>
    </div>
  );
}

/* -- part art: tiny stylized side-elevation shapes, drawn as SVG so the
 *    exploded view is crisp at any size. Colors are token roles. -- */

const STROKE = "#3a3a48";

function PartOutsole() {
  return (
    <svg viewBox="0 0 200 60" className="orbit-build__svg">
      <path
        d="M 8 38 Q 10 52 26 52 L 174 52 Q 192 52 194 38 L 192 30 Q 100 44 8 30 Z"
        fill="#0d0d12"
        stroke={STROKE}
        strokeWidth="1.2"
      />
      {/* tread blocks */}
      {Array.from({ length: 8 }, (_, i) => {
        const x = 24 + i * 19;
        return (
          <line
            key={i}
            x1={x}
            y1={40}
            x2={x}
            y2={50}
            stroke={withAlpha("#e8eef5", 0.25)}
            strokeWidth="1.4"
          />
        );
      })}
    </svg>
  );
}

function PartMidsole() {
  return (
    <svg viewBox="0 0 200 60" className="orbit-build__svg">
      <path
        d="M 6 44 L 194 44 L 178 22 Q 100 34 22 22 Z"
        fill="#e8eef5"
        stroke={STROKE}
        strokeWidth="1.2"
      />
      <path
        d="M 22 22 Q 100 34 178 22"
        fill="none"
        stroke={withAlpha("#0d0d12", 0.18)}
        strokeWidth="1"
      />
    </svg>
  );
}

function PartUpper() {
  return (
    <svg viewBox="0 0 200 70" className="orbit-build__svg">
      <path
        d="M 14 60 Q 12 40 30 30 Q 60 16 96 18 Q 120 20 140 14 Q 168 8 184 30 Q 188 44 182 58 Q 100 66 14 60 Z"
        fill="#3a2218"
        stroke={STROKE}
        strokeWidth="1.2"
      />
      {/* accent stripe */}
      <path
        d="M 150 26 Q 110 38 70 44 Q 96 30 150 26 Z"
        fill="#ff5722"
      />
      {/* collar opening */}
      <path
        d="M 150 16 Q 138 10 124 14 Q 136 20 150 16 Z"
        fill="#0d0d12"
        opacity="0.55"
      />
    </svg>
  );
}

function PartLaces() {
  return (
    <svg viewBox="0 0 200 40" className="orbit-build__svg">
      {[0, 1, 2, 3].map((i) => (
        <g key={i}>
          <circle cx={60 + i * 22} cy={20} r={5} fill={withAlpha("#9aa0ad", 0.3)} stroke={STROKE} strokeWidth="1" />
          <line
            x1={60 + i * 22}
            y1={20}
            x2={60 + i * 22 + 10}
            y2={20}
            stroke="#9aa0ad"
            strokeWidth="2.4"
            strokeLinecap="round"
          />
        </g>
      ))}
      <line x1="40" y1="20" x2="150" y2="20" stroke={STROKE} strokeWidth="0.8" strokeDasharray="3 4" />
    </svg>
  );
}

function PartCounter() {
  return (
    <svg viewBox="0 0 120 70" className="orbit-build__svg">
      <path
        d="M 20 60 Q 14 30 40 16 Q 70 8 96 18 Q 104 30 100 58 Q 60 64 20 60 Z"
        fill={withAlpha("#241208", 0.85)}
        stroke={STROKE}
        strokeWidth="1.2"
      />
      <path
        d="M 40 16 Q 70 8 96 18"
        fill="none"
        stroke={withAlpha("#ff5722", 0.4)}
        strokeWidth="1.4"
      />
    </svg>
  );
}

"use client";

import { useCallback, useEffect, useRef, type PointerEvent as ReactPointerEvent } from "react";
import {
  COLORWAYS,
  drawSneaker,
  type Colorway,
} from "./sneaker";
import { useOrbit } from "../hooks/useOrbit";

/** Backing-store resolution cap — a 2.5D silhouette gains nothing above 2. */
const MAX_DPR = 2;

type Props = {
  colorway: Colorway["id"];
  reduced: boolean;
};

/**
 * The turntable. A DPR-capped canvas draws the sneaker (and its floor
 * reflection) every frame from the live orbit state, read off the ref —
 * never React state. A DOM contact-shadow layer beneath it foreshortens
 * and re-centers with rotation.
 *
 * Drag rotates the product 1:1; release flings with inertia. The key light
 * holds while you drag and circles on its own after a few seconds of quiet,
 * so touch devices still see a living specular. Under reduced motion the
 * orbit is 1:1 with no inertia and the light is held — the shoe is a still
 * you can re-pose.
 *
 * The canvas owns one rAF, paused when the stage leaves the viewport and
 * when the tab hides. The stage is a real focusable control: left/right
 * arrow keys nudge the angle, Home resets it.
 */
export default function ProductTurntable({ colorway, reduced }: Props) {
  const stageRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const shadowRef = useRef<HTMLDivElement | null>(null);
  const cwRef = useRef<Colorway>(COLORWAYS[colorway]);

  useEffect(() => {
    cwRef.current = COLORWAYS[colorway];
  }, [colorway]);

  const orbit = useOrbit(reduced);

  useEffect(() => {
    const canvas = canvasRef.current;
    const stage = stageRef.current;
    const shadow = shadowRef.current;
    if (!canvas || !stage || !shadow) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let raf = 0;
    let running = false;
    let visible = false;

    const resize = () => {
      const rect = stage.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) return;
      const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
      canvas.width = Math.round(rect.width * dpr);
      canvas.height = Math.round(rect.height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const draw = () => {
      const s = orbit.ref.current;
      const rect = stage.getBoundingClientRect();
      drawSneaker(ctx, {
        angle: s.angle,
        keyAzimuth: s.keyAzimuth,
        grab: s.grab,
        cw: cwRef.current,
        w: rect.width,
        h: rect.height,
      });
      // Contact shadow foreshortens with |cos(angle)| and softens on grab.
      const cos = Math.abs(Math.cos(s.angle));
      const scaleX = 0.78 + 0.22 * cos;
      const opacity = Math.max(0.3, 0.55 + 0.25 * cos - s.grab * 0.15);
      shadow.style.setProperty("--orbit-shadow-sx", scaleX.toFixed(3));
      shadow.style.setProperty("--orbit-shadow-op", opacity.toFixed(3));
      shadow.style.setProperty("--orbit-shadow-lift", `${(s.grab * 6).toFixed(1)}px`);
    };

    const frame = () => {
      raf = requestAnimationFrame(frame);
      draw();
    };

    const start = () => {
      if (running) return;
      running = true;
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };
    const sync = () => {
      const should = visible && !document.hidden;
      if (should) start();
      else stop();
    };

    resize();
    draw(); // first frame — also the reduced-motion still

    const ro = new ResizeObserver(() => {
      resize();
      if (!running) draw();
    });
    ro.observe(stage);

    const io = new IntersectionObserver(
      (hits) => {
        visible = hits[hits.length - 1].isIntersecting;
        orbit.setVisible(visible);
        sync();
      },
      { rootMargin: "80px 0px" },
    );
    io.observe(stage);

    const onVis = () => sync();
    document.addEventListener("visibilitychange", onVis);

    orbit.sync(); // start the orbit's angle/key-light rAF

    return () => {
      stop();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [orbit]);

  const onKeyDown = useCallback((ev: React.KeyboardEvent<HTMLDivElement>) => {
    const step = Math.PI / 12; // 15° per press
    if (ev.key === "ArrowLeft") {
      orbit.nudge(step);
      ev.preventDefault();
    } else if (ev.key === "ArrowRight") {
      orbit.nudge(-step);
      ev.preventDefault();
    } else if (ev.key === "Home") {
      orbit.reset();
      ev.preventDefault();
    }
  }, [orbit]);

  const deg = Math.round(
    ((((orbit.state.angle * 180) / Math.PI) % 360) + 360) % 360,
  );

  return (
    <div
      ref={stageRef}
      className="orbit-stage"
      role="slider"
      tabIndex={0}
      aria-label="Product turntable — drag to orbit the sneaker 360 degrees. Use left and right arrow keys to rotate, Home to reset. 제품 턴테이블 — 드래그해 스니커즈를 360도로 돌아보세요. 좌우 화살표 키로 회전, Home 키로 되돌리기."
      aria-valuemin={0}
      aria-valuemax={360}
      aria-valuenow={deg}
      onKeyDown={onKeyDown}
      {...orbit.handlers}
    >
      {/* Affordance ring — 36 ticks at 10° each, purely decorative */}
      <div className="orbit-stage__ring" aria-hidden="true">
        {Array.from({ length: 36 }, (_, i) => (
          <span
            key={i}
            className="orbit-stage__tick"
            style={{ transform: `rotate(${i * 10}deg)` }}
          />
        ))}
      </div>

      {/* Contact shadow — foreshortens with rotation */}
      <div ref={shadowRef} className="orbit-stage__shadow" aria-hidden="true" />

      {/* The product (canvas draws the sneaker + its floor reflection) */}
      <canvas
        ref={canvasRef}
        className="orbit-stage__canvas"
        aria-hidden="true"
      />

      {/* Drag hint, fades after first interaction */}
      <p
        className="orbit-stage__hint"
        aria-hidden="true"
        data-active={orbit.state.grab < 0.5 ? "true" : "false"}
      >
        drag to orbit · <span lang="ko">드래그해 돌아보기</span>
      </p>

      {/* Angle readout — a studio instrument read */}
      <p className="orbit-stage__readout" aria-hidden="true">
        <span className="orbit-stage__readout-deg">{String(deg).padStart(3, "0")}°</span>
        <span className="orbit-stage__readout-ko" lang="ko">
          회전각
        </span>
      </p>
    </div>
  );
}

/**
 * ORBIT sneaker renderer — a procedural canvas 2.5D turntable.
 *
 * The product is drawn in code, never as an image. The trick: instead of
 * pre-rendering 36 discrete sprite angles and cross-fading, we draw ONE
 * continuous side-elevation silhouette whose entire shape is a function of
 * the orbit angle. As `angle` sweeps 0 → 2π the silhouette's effective
 * width foreshortens (cos), the visible side swaps (the swoosh flips and
 * the laces occlude differently), and a specular streak travels the upper
 * — so a single parameterized drawing reads as a continuous 360° orbit.
 *
 * This is "2.5D" honestly stated: there is no mesh, no perspective matrix.
 * There is a side profile that breathes with the turntable. The contact
 * shadow (a DOM layer in ProductTurntable) and the floor reflection (drawn
 * here, below the ground line, as a flipped faded copy) do the rest of the
 * depth work.
 *
 * Every color arrives as a CSS-parsed token from the caller; this module
 * owns no hexes (the two studio-light tints, #fff5e6 and #b8d8ff, are
 * passed through from tokens.json roles "key-light" and "rim-light" — kept
 * as named constants only to avoid repeating string literals).
 */

export type Colorway = {
  id: "ember" | "ocean" | "frost";
  /** Primary upper color (the dominant panel). */
  upper: string;
  /** Secondary / overlay panel (toe box, heel counter). */
  overlay: string;
  /** The signature accent stripe. */
  accent: string;
  /** Midsole foam. */
  midsole: string;
  /** Outsole rubber. */
  outsole: string;
  /** Lace + collar trim. */
  trim: string;
};

export const COLORWAYS: Record<Colorway["id"], Colorway> = {
  ember: {
    id: "ember",
    upper: "#3a2218",
    overlay: "#241208",
    accent: "#ff5722",
    midsole: "#e8eef5",
    outsole: "#0d0d12",
    trim: "#9aa0ad",
  },
  ocean: {
    id: "ocean",
    upper: "#0a1a3a",
    overlay: "#040d22",
    accent: "#0066ff",
    midsole: "#e8eef5",
    outsole: "#0d0d12",
    trim: "#9aa0ad",
  },
  frost: {
    id: "frost",
    upper: "#c4ccd6",
    overlay: "#9aa0ad",
    accent: "#ff5722",
    midsole: "#ffffff",
    outsole: "#2a2a36",
    trim: "#3a3a48",
  },
};

/** Key-light and rim-light tints (token roles, inlined to avoid magic strings). */
const KEY = "#fff5e6";
const RIM = "#b8d8ff";

export type RenderOpts = {
  /** Orbit angle in radians, [0, 2π). 0 = full medial side, right-facing. */
  angle: number;
  /** Key-light azimuth in radians — the specular streak tracks this. */
  keyAzimuth: number;
  /** 0..1 grab factor — nudges the silhouette into a subtle "lift". */
  grab: number;
  /** 0..1 exploded factor — separates the parts vertically (the build view). */
  explode?: number;
  cw: Colorway;
  /** Canvas pixel width (CSS px, already DPR-scaled by caller's transform). */
  w: number;
  /** Canvas pixel height (CSS px). */
  h: number;
};

/** Useful derived quantities exposed for the shadow layer. */
export type SilhouetteMetrics = {
  /** Effective half-width of the silhouette at this angle, in stage units. */
  halfWidth: number;
  /** Ground line y (where the sole meets the floor), in CSS px from top. */
  soleY: number;
  /** Overall silhouette height in CSS px. */
  height: number;
};

/**
 * Draw the sneaker (plus its floor reflection) into the given 2D context.
 * The context is expected to be pre-scaled for DPR by the caller; we draw
 * in CSS pixels. Origin: top-left. Returns metrics for the contact shadow.
 */
export function drawSneaker(
  ctx: CanvasRenderingContext2D,
  o: RenderOpts,
): SilhouetteMetrics {
  const { w, h } = o;
  ctx.save();
  ctx.clearRect(0, 0, w, h);

  const m = drawSneakerBody(ctx, o);

  // Floor reflection: a vertically-flipped, faded copy of the silhouette
  // drawn below the ground line. We reflect about soleY and squash vertically
  // so it reads as lying on the floor, not a mirror floating below.
  const groundY = m.soleY;
  ctx.save();
  ctx.globalAlpha = 0.16;
  ctx.translate(0, groundY * 2);
  ctx.scale(1, -0.62); // flip + foreshorten the reflection onto the floor
  drawSneakerBody(ctx, o);
  ctx.restore();

  ctx.restore();
  return m;
}

/**
 * Draw just the sneaker body (no reflection, no clear). Called twice by
 * drawSneaker: once upright, once flipped for the reflection. Origin is
 * top-left of the canvas; all placement derives from w/h.
 */
function drawSneakerBody(ctx: CanvasRenderingContext2D, o: RenderOpts): SilhouetteMetrics {
  const { w, h, angle, keyAzimuth, cw } = o;
  const grab = o.grab ?? 0;
  const explode = o.explode ?? 0;

  const cx = w / 2;
  const groundY = h * 0.78;
  const UNIT = Math.min(w, h) / 7.2; // the shoe is ~6 units long

  const c = Math.cos(angle);
  const foreshorten = Math.abs(c);
  const a = ((angle % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
  // "Near side" (laces/swoosh face us) when the shoe hasn't turned past 90°.
  const nearSide = a < Math.PI / 2 || a > (Math.PI * 3) / 2;

  const lengthU = 1.65 + 0.95 * foreshorten; // 1.65 .. 2.6 units
  const halfLen = lengthU * UNIT;
  const heightU = 1.5;
  const height = heightU * UNIT;
  const lift = grab * UNIT * 0.06;

  ctx.save();
  ctx.translate(cx, groundY - lift);

  // ---- outsole ------------------------------------------------------------
  const soleHalfW = halfLen * 0.98;
  const soleH = UNIT * 0.16;
  roundRectPath(ctx, -soleHalfW, -soleH, soleHalfW * 2, soleH, soleH * 0.5);
  ctx.fillStyle = cw.outsole;
  ctx.fill();
  if (foreshorten > 0.35) {
    ctx.fillStyle = withAlpha(cw.midsole, 0.12);
    const notches = 7;
    for (let i = 1; i < notches; i++) {
      const x = -soleHalfW + (i / notches) * soleHalfW * 2;
      ctx.fillRect(x - UNIT * 0.02, -soleH * 0.7, UNIT * 0.04, soleH * 0.5);
    }
  }

  // ---- midsole (foam wedge) -----------------------------------------------
  const soleHRef = soleH;
  ctx.save();
  ctx.translate(0, -soleHRef);
  const midHalfW = halfLen;
  const midH = UNIT * 0.22;
  ctx.beginPath();
  ctx.moveTo(-midHalfW, 0);
  ctx.lineTo(midHalfW, 0);
  ctx.lineTo(midHalfW * 0.82, -midH);
  ctx.quadraticCurveTo(-midHalfW * 0.5, -midH * 1.18, -midHalfW, -midH * 0.4);
  ctx.closePath();
  ctx.fillStyle = cw.midsole;
  ctx.fill();
  ctx.save();
  ctx.clip();
  const midGrad = ctx.createLinearGradient(0, -midH, 0, 0);
  midGrad.addColorStop(0, withAlpha(cw.midsole, 0));
  midGrad.addColorStop(1, withAlpha(cw.outsole, 0.28));
  ctx.fillStyle = midGrad;
  ctx.fillRect(-midHalfW, -midH, midHalfW * 2, midH);
  ctx.restore();
  ctx.restore();

  // ---- upper (the main body) ---------------------------------------------
  const baseY = -soleHRef - midH; // relative to the translate(cx, groundY)
  const upperTopOffset = explode > 0 ? explode * UNIT * 1.6 : 0;
  const upperHalfW = halfLen * 0.96;

  ctx.save();
  ctx.translate(0, baseY);
  if (upperTopOffset) ctx.translate(0, -upperTopOffset);

  // Normalized profile helper: nx in [-1,1] (toe+, heel-), uy in units above sole.
  const P = (nx: number, uy: number): [number, number] => [
    nx * upperHalfW,
    -uy * UNIT,
  ];
  ctx.beginPath();
  let pt = P(1.0, 0.18);
  ctx.moveTo(pt[0], pt[1]);
  pt = P(0.72, 0.42);
  ctx.quadraticCurveTo(P(0.92, 0.3)[0], P(0.92, 0.3)[1], pt[0], pt[1]);
  pt = P(0.34, 0.62);
  ctx.quadraticCurveTo(P(0.55, 0.5)[0], P(0.55, 0.5)[1], pt[0], pt[1]);
  pt = P(0.02, 0.5);
  ctx.quadraticCurveTo(P(0.18, 0.6)[0], P(0.18, 0.6)[1], pt[0], pt[1]);
  pt = P(-0.34, 1.18);
  ctx.quadraticCurveTo(P(-0.12, 0.62)[0], P(-0.12, 0.62)[1], pt[0], pt[1]);
  pt = P(-0.5, 1.22);
  ctx.quadraticCurveTo(P(-0.42, 1.24)[0], P(-0.42, 1.24)[1], pt[0], pt[1]);
  pt = P(-0.92, 0.7);
  ctx.quadraticCurveTo(P(-0.7, 1.1)[0], P(-0.7, 1.1)[1], pt[0], pt[1]);
  pt = P(-1.0, 0.1);
  ctx.quadraticCurveTo(P(-0.98, 0.4)[0], P(-0.98, 0.4)[1], pt[0], pt[1]);
  ctx.closePath();
  ctx.fillStyle = cw.upper;
  ctx.fill();

  // Body shading driven by the key light azimuth. Its projected direction
  // onto the visible side is sin(keyAzimuth - angle).
  const lightDir = Math.sin(keyAzimuth - angle);
  const shadeGrad = ctx.createLinearGradient(
    -upperHalfW * lightDir,
    0,
    upperHalfW * lightDir,
    0,
  );
  shadeGrad.addColorStop(0, withAlpha(cw.overlay, 0.55));
  shadeGrad.addColorStop(0.5, withAlpha(cw.overlay, 0));
  shadeGrad.addColorStop(1, withAlpha(KEY, 0.1));
  ctx.save();
  ctx.clip();
  ctx.fillStyle = shadeGrad;
  ctx.fillRect(-upperHalfW, -height, upperHalfW * 2, height);
  ctx.restore();

  // ---- overlay panels (toe cap + heel counter) ----------------------------
  ctx.save();
  ctx.clip();
  // toe cap
  ctx.beginPath();
  pt = P(1.0, 0);
  ctx.moveTo(pt[0], pt[1]);
  pt = P(1.0, 0.5);
  ctx.lineTo(pt[0], pt[1]);
  pt = P(0.4, 0.62);
  ctx.quadraticCurveTo(P(0.7, 0.55)[0], P(0.7, 0.55)[1], pt[0], pt[1]);
  pt = P(0.2, 0.2);
  ctx.quadraticCurveTo(P(0.3, 0.5)[0], P(0.3, 0.5)[1], pt[0], pt[1]);
  ctx.closePath();
  ctx.fillStyle = cw.overlay;
  ctx.fill();
  // heel counter
  ctx.beginPath();
  pt = P(-1.0, 0);
  ctx.moveTo(pt[0], pt[1]);
  pt = P(-1.0, 0.95);
  ctx.lineTo(pt[0], pt[1]);
  pt = P(-0.5, 1.24);
  ctx.quadraticCurveTo(P(-0.8, 1.15)[0], P(-0.8, 1.15)[1], pt[0], pt[1]);
  pt = P(-0.2, 0.5);
  ctx.quadraticCurveTo(P(-0.4, 1.0)[0], P(-0.4, 1.0)[1], pt[0], pt[1]);
  ctx.closePath();
  ctx.fillStyle = withAlpha(cw.overlay, 0.75);
  ctx.fill();
  ctx.restore();

  // ---- the accent stripe ("swoosh") — near side only ----------------------
  if (nearSide) {
    ctx.beginPath();
    pt = P(0.42, 0.34);
    ctx.moveTo(pt[0], pt[1]);
    ctx.bezierCurveTo(
      P(0.1, 0.2)[0], P(0.1, 0.2)[1],
      P(-0.28, 0.46)[0], P(-0.28, 0.46)[1],
      P(-0.42, 0.62)[0], P(-0.42, 0.62)[1],
    );
    ctx.bezierCurveTo(
      P(-0.34, 0.5)[0], P(-0.34, 0.5)[1],
      P(-0.2, 0.4)[0], P(-0.2, 0.4)[1],
      P(0.3, 0.28)[0], P(0.3, 0.28)[1],
    );
    ctx.closePath();
    ctx.fillStyle = cw.accent;
    ctx.fill();
  }

  // ---- laces + collar trim (near side, not at front/back) -----------------
  if (nearSide && foreshorten > 0.25) {
    ctx.strokeStyle = cw.trim;
    ctx.lineWidth = UNIT * 0.05;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(...P(-0.5, 1.16));
    ctx.quadraticCurveTo(...P(-0.3, 1.28), ...P(-0.1, 1.02));
    ctx.stroke();
    const laceY0 = 0.66;
    const laceY1 = 0.86;
    for (let i = 0; i < 4; i++) {
      const t = i / 3;
      const x0 = 0.06 + t * 0.22;
      ctx.beginPath();
      ctx.moveTo(...P(x0, laceY0));
      ctx.lineTo(...P(x0 + 0.06, laceY1));
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(...P(0.04, 0.66));
    ctx.quadraticCurveTo(...P(0.18, 0.78), ...P(0.32, 0.66));
    ctx.strokeStyle = withAlpha(cw.overlay, 0.9);
    ctx.lineWidth = UNIT * 0.03;
    ctx.stroke();
  }

  // ---- specular streak — the read of "real light" -------------------------
  if (foreshorten > 0.18) {
    const specCenterX = Math.sin(keyAzimuth) * upperHalfW * 0.5;
    const specGrad = ctx.createLinearGradient(
      specCenterX - UNIT * 0.5,
      0,
      specCenterX + UNIT * 0.5,
      0,
    );
    specGrad.addColorStop(0, withAlpha(KEY, 0));
    specGrad.addColorStop(0.5, withAlpha(KEY, 0.22));
    specGrad.addColorStop(1, withAlpha(KEY, 0));
    ctx.save();
    ctx.clip();
    ctx.fillStyle = specGrad;
    ctx.fillRect(specCenterX - UNIT * 0.6, -height, UNIT * 1.2, height);
    ctx.restore();
  }

  // ---- rim-light edge on the shadow side (cool kicker) -------------------
  if (foreshorten > 0.2) {
    ctx.save();
    ctx.clip();
    ctx.strokeStyle = withAlpha(RIM, 0.18);
    ctx.lineWidth = UNIT * 0.04;
    ctx.stroke(); // stroke the current upper path as a rim
    ctx.restore();
  }

  ctx.restore(); // upper group
  ctx.restore(); // body translate

  return { halfWidth: halfLen, soleY: groundY, height };
}

/** Helper: rounded-rectangle path (no fill — caller fills/strokes). */
function roundRectPath(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
): void {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

/**
 * Apply alpha to a color token. Accepts #hex (3 or 6 digit) or rgb()/rgba();
 * returns an rgba() string. Keeps every color token-driven: callers pass the
 * same token they'd paint with, we re-emit it at a chosen opacity.
 */
export function withAlpha(color: string, alpha: number): string {
  const a = Math.max(0, Math.min(1, alpha));
  if (color.startsWith("#")) {
    const hex = color.slice(1);
    const full =
      hex.length === 3
        ? hex
            .split("")
            .map((ch) => ch + ch)
            .join("")
        : hex;
    const r = parseInt(full.slice(0, 2), 16);
    const g = parseInt(full.slice(2, 4), 16);
    const b = parseInt(full.slice(4, 6), 16);
    return `rgba(${r},${g},${b},${a})`;
  }
  const m = /^rgba?\(([^)]+)\)$/.exec(color);
  if (m) {
    const parts = m[1].split(",").map((s) => s.trim());
    const [r, g, b] = parts;
    return `rgba(${r},${g},${b},${a})`;
  }
  return color;
}

// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/inter";
import "@fontsource/noto-sans-kr";
import "@fontsource/space-grotesk";

export const inter = { variable: "" };
export const notoSansKR = { variable: "" };
export const spaceGrotesk = { variable: "" };

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/** Inertia decay per 60fps-normalized frame. */
const INERTIA = 0.96;
/** Angular lerp toward target, per 60fps-normalized frame. */
const ANGLE_LERP = 0.32;
/** After this many ms of orbit silence, the key light drifts on its own. */
const IDLE_MS = 4000;
/** Key-light autonomous drift, radians per second. */
const KEY_DRIFT = 0.06;
/** Drag maps pointer px → radians. One full drag-width ≈ a half turn. */
const DRAG_GAIN = 0.0085;
/** Floor angular velocity (rad/s) so inertia always visibly settles. */
const MIN_VEL = 0.04;
/** Max angular velocity (rad/s) to keep a fling readable. */
const MAX_VEL = 14;
/** Angle bucket size (radians) for coarse React state updates. */
const BUCKET = Math.PI / 6; // 30°

export type OrbitState = {
  /** The orbit angle the canvas should render, in radians, wrapped to [0,2π). */
  angle: number;
  /** The key-light azimuth, in radians. The specular travels with it. */
  keyAzimuth: number;
  /** 0..1 — how much the visitor is "holding" the shoe right now. */
  grab: number;
};

/**
 * The turntable's physics. Returns:
 *   - `state`   — the latest OrbitState, for one-time React reads (the angle
 *                 readout, the "drag to orbit" hint). Updated only when the
 *                 angle crosses a 30° bucket, to avoid per-frame re-renders.
 *   - `ref`     — a mutable ref to the live OrbitState, read every animation
 *                 frame by the canvas. This is the hot path; React is not.
 *   - `setVisible` / `sync` — call from the stage's IntersectionObserver so
 *                 the rAF pauses offscreen.
 *   - `handlers`— `onPointerDown/Move/Up/Leave/Cancel` to spread on the stage.
 *
 * The drag is 1:1 with pointer delta (a turn feels like turning the shoe).
 * On release, the last drag velocity becomes inertia, decaying at INERTIA/
 * frame; under reduced motion there is no inertia and no angle lerp — the
 * shoe goes exactly where you put it, and stops.
 *
 * The loop advances the angle from inertia and eases it toward target with
 * ANGLE_LERP, advances the key light (autonomously after IDLE_MS, or held
 * while dragging), and eases `grab`. It owns one rAF, paused when the stage
 * leaves the viewport (toggled via `setVisible`) and when the tab hides.
 */
const INITIAL_ANGLE = 0.42;

export function useOrbit(reduced: boolean) {
  const live = useRef<OrbitState>({
    angle: INITIAL_ANGLE,
    keyAzimuth: 0.5,
    grab: 0,
  });
  const target = useRef<number>(INITIAL_ANGLE);
  const vel = useRef<number>(0);
  const dragging = useRef(false);
  const lastDragX = useRef(0);
  const lastDragT = useRef(0);
  const lastMoveT = useRef(-1e9);
  const visible = useRef(true);
  const raf = useRef(0);
  const running = useRef(false);
  const frameRef = useRef<(now: number) => void>(() => {});

  // React-facing bucketed state (only fires on coarse changes). Seeded from
  // the same initial constants as the refs above (not from ref reads, which
  // the lint rule forbids at render).
  const [state, setState] = useState<OrbitState>({
    angle: INITIAL_ANGLE,
    keyAzimuth: 0.5,
    grab: 0,
  });
  const lastBucket = useRef(Math.round(INITIAL_ANGLE / BUCKET));

  const setVisible = useCallback((v: boolean) => {
    visible.current = v;
  }, []);

  // Wire frame into sync via a ref so sync never closes over a stale frame.
  const sync = useCallback(() => {
    const should = visible.current && !document.hidden;
    if (should && !running.current) {
      running.current = true;
      raf.current = requestAnimationFrame((t) => frameRef.current(t));
    } else if (!should && running.current) {
      running.current = false;
      cancelAnimationFrame(raf.current);
    }
  }, []);

  const frame = useCallback(
    (now: number) => {
      raf.current = requestAnimationFrame((t) => frameRef.current(t));
      const s = live.current;

      // Angle: inertia + lerp toward target. rAF cadence is the clock; the
      // constants are tuned for ~60fps, and dt clamping is unnecessary
      // because inertia decays per-frame regardless of wall time.
      if (!reduced) {
        if (Math.abs(vel.current) > MIN_VEL) {
          target.current += vel.current * (1 / 60);
          vel.current *= INERTIA;
        } else {
          vel.current = 0;
        }
      }
      const lerpK = reduced ? 1 : ANGLE_LERP;
      s.angle += (target.current - s.angle) * lerpK;
      if (s.angle < 0) s.angle += Math.PI * 2;
      if (s.angle >= Math.PI * 2) s.angle -= Math.PI * 2;

      // Key light: held while dragging, autonomous drift after idle.
      const idle = now - lastMoveT.current > IDLE_MS;
      if (idle && !reduced) s.keyAzimuth += KEY_DRIFT / 60;

      // Grab ease.
      const grabTarget = dragging.current ? 1 : 0;
      s.grab += (grabTarget - s.grab) * (reduced ? 1 : 0.18);

      // Coarse state push — only when the 30° bucket changes.
      const bucket = Math.round(s.angle / BUCKET);
      if (bucket !== lastBucket.current) {
        lastBucket.current = bucket;
        setState({ angle: s.angle, keyAzimuth: s.keyAzimuth, grab: s.grab });
      }
    },
    [reduced],
  );

  // Keep the ref current without reading it during render.
  useEffect(() => {
    frameRef.current = frame;
  }, [frame]);

  // Visibility + tab-hidden handling.
  useEffect(() => {
    const onVis = () => sync();
    document.addEventListener("visibilitychange", onVis);
    return () => {
      document.removeEventListener("visibilitychange", onVis);
      running.current = false;
      cancelAnimationFrame(raf.current);
    };
  }, [sync]);

  // Pointer handlers — spread on the stage element.
  const onPointerDown = useCallback(
    (ev: React.PointerEvent) => {
      dragging.current = true;
      lastDragX.current = ev.clientX;
      lastDragT.current = performance.now();
      lastMoveT.current = performance.now();
      vel.current = 0;
      (ev.target as Element).setPointerCapture?.(ev.pointerId);
      sync();
    },
    [sync],
  );

  const onPointerMove = useCallback((ev: React.PointerEvent) => {
    if (!dragging.current) return;
    const now = performance.now();
    const dx = ev.clientX - lastDragX.current;
    const dt = Math.max(8, now - lastDragT.current);
    lastDragX.current = ev.clientX;
    lastDragT.current = now;
    lastMoveT.current = now;
    // Apply the delta to the live angle immediately (1:1 drag feel) and to
    // the target; track velocity for the inertia on release.
    const delta = dx * DRAG_GAIN;
    target.current += delta;
    live.current.angle += delta;
    const v = (delta / dt) * 1000; // rad/s
    vel.current = Math.max(-MAX_VEL, Math.min(MAX_VEL, v));
  }, []);

  const endDrag = useCallback(
    (ev: React.PointerEvent) => {
      if (!dragging.current) return;
      dragging.current = false;
      (ev.target as Element).releasePointerCapture?.(ev.pointerId);
      if (reduced) vel.current = 0;
      sync();
    },
    [reduced, sync],
  );

  /** Keyboard nudge: step the angle directly (arrow keys / Home reset). */
  const nudge = useCallback((delta: number) => {
    live.current.angle += delta;
    if (live.current.angle < 0) live.current.angle += Math.PI * 2;
    if (live.current.angle >= Math.PI * 2) live.current.angle -= Math.PI * 2;
    target.current = live.current.angle;
  }, []);

  /** Reset to the home angle. */
  const reset = useCallback(() => {
    live.current.angle = INITIAL_ANGLE;
    target.current = INITIAL_ANGLE;
  }, []);

  return {
    state,
    ref: live,
    setVisible,
    sync,
    nudge,
    reset,
    handlers: {
      onPointerDown,
      onPointerMove,
      onPointerUp: endDrag,
      onPointerLeave: endDrag,
      onPointerCancel: endDrag,
    },
  };
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, type RefObject } from "react";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class. The pre-reveal state (opacity/translate)
 * lives in styles.css and is gated behind the `.orbit-js` root class, so the
 * content is fully visible when JavaScript never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms
 * apart via transition-delay, so a screenful never fades as one slab.
 */
export function useReveal(
  rootRef: RefObject<HTMLElement | null>,
  disabled: boolean,
): void {
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (disabled || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.15, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [rootRef, disabled]);
}

"use client";

import { useEffect, useRef, type RefObject } from "react";

/** Frame-rate-independent smoothing per 60fps-normalized frame. */
const LERP = 0.18;

/**
 * Tracks scroll progress through a pinned section and writes a smoothed
 * 0→1 value to a custom property on the pinned element.
 *
 * `progressVar` names the CSS custom property written (default
 * `--orbit-build`); the exploded build's part offsets and rail clips read it.
 * The raw (unsmoothed) progress is written to `<progressVar>-raw` so scrub-
 * dependent things that must not lag (clip-path wipes) can use it directly.
 *
 * This is direct input→style manipulation (scroll position → a number), not
 * an autonomous animation, so it stays live under prefers-reduced-motion —
 * only the *lerp* is bypassed there, so the build still responds 1:1 to the
 * wheel.
 */
export function useScrollProgress(
  pinRef: RefObject<HTMLElement | null>,
  progressVar = "--orbit-build",
): void {
  const rafRef = useRef(0);
  const smoothRef = useRef(0);

  useEffect(() => {
    const el = pinRef.current;
    if (!el) return;

    let lastTarget = 0;

    const compute = () => {
      rafRef.current = 0;
      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      // 0 when the section's top hits the top of the viewport,
      // 1 when its bottom hits the bottom. The section is taller than the
      // viewport on purpose (it is the pin's runway).
      const usable = Math.max(1, rect.height - vh);
      const traveled = Math.min(Math.max(-rect.top, 0), usable);
      lastTarget = traveled / usable;
      el.style.setProperty(`${progressVar}-raw`, lastTarget.toFixed(4));
    };

    const tick = () => {
      rafRef.current = 0;
      smoothRef.current += (lastTarget - smoothRef.current) * LERP;
      el.style.setProperty(progressVar, smoothRef.current.toFixed(4));
    };

    const scheduleCompute = () => {
      if (!rafRef.current) {
        rafRef.current = requestAnimationFrame(() => {
          compute();
          tick();
        });
      }
    };

    compute();
    smoothRef.current = lastTarget; // no spring on first paint
    el.style.setProperty(progressVar, smoothRef.current.toFixed(4));

    window.addEventListener("scroll", scheduleCompute, { passive: true });
    window.addEventListener("resize", scheduleCompute, { passive: true });
    return () => {
      window.removeEventListener("scroll", scheduleCompute);
      window.removeEventListener("resize", scheduleCompute);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [pinRef, progressVar]);
}

"use client";

import { useEffect, useRef, useState } from "react";
import "./styles.css";
import { inter, notoSansKR, spaceGrotesk } from "./fonts";
import Hero from "./components/Hero";
import ExplodedBuild from "./components/ExplodedBuild";
import ColorwayPicker from "./components/ColorwayPicker";
import OrbitFooter from "./components/OrbitFooter";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useReveal } from "./hooks/useReveal";
import type { Colorway } from "./components/sneaker";

/**
 * ORBIT — studio configurator. A fictional studio that drops one silhouette
 * at a time; the page IS the configurator. A procedural canvas turntable
 * holds the signature sneaker under a seamless cyclorama — drag to orbit it
 * 360° with real specular lighting and a turntable contact shadow. Three
 * colorways, an exploded build scrubbed by scroll, and panels that wipe in.
 *
 * `.orbit-js` is added on mount so every scroll-reveal and clip-wipe
 * pre-state is JS-gated — with JavaScript disabled the full page is simply
 * readable, the canvas turntable replaced by its CSS seamless understudy
 * and the angle held at the hero pose.
 */
export default function OrbitPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const [colorway, setColorway] = useState<Colorway["id"]>("ember");

  useReveal(rootRef, reduced);

  useEffect(() => {
    rootRef.current?.classList.add("orbit-js");
    window.parent?.postMessage(
      { type: "oneshot:ready", slug: "orbit" },
      "*",
    );
  }, []);

  return (
    <div
      id="orbit-top"
      ref={rootRef}
      // `orbit-js` is NOT in the className on purpose: it is added on mount
      // by the effect above so the SSR/ no-JS markup is the completed page,
      // and every reveal pre-state (gated behind .orbit-js) stays hidden only
      // when JavaScript is actually alive.
    >
      <Hero colorway={colorway} reduced={reduced} />
      <main>
        <ExplodedBuild />
        <ColorwayPicker colorway={colorway} onPick={setColorway} />
      </main>
      <OrbitFooter />
    </div>
  );
}

/* ==========================================================================
   ORBIT — studio configurator
   three-d-immersive · seamless studio, key/rim light, ember accent · tokens
   Scoped by convention to .orbit-root; classes prefixed orbit-.
   ========================================================================== */

.orbit-root {
  /* -- palette ---------------------------------------------------------- */
  --orbit-floor: #1a1a22;          /* studio floor — the seamless ground */
  --orbit-rise: #2a2a36;           /* the floor lifting into the cyclorama */
  --orbit-ink: #0d0d12;            /* deepest shadow — turntable base, footer well */
  --orbit-ember: #ff5722;          /* hero accent, focus ring, default colorway, call-outs (4.9:1 large on floor) */
  --orbit-ocean: #0066ff;          /* second colorway; rim-light tint on readouts (4.6:1 — labels only) */
  --orbit-frost: #e8eef5;          /* third colorway; primary text (14.6:1) + specular highlight */
  --orbit-frost-dim: #9aa0ad;      /* secondary text — frost at ~60% over floor (7.0:1) */
  --orbit-key: #fff5e6;            /* warm key light tinting lit side + specular */
  --orbit-rim: #b8d8ff;            /* cool rim light raking the shadow side */
  --orbit-hairline: #3a3a48;       /* decorative only (2.6:1): dividers, panel borders, rails */

  /* -- turntable shadow driver vars (written by JS each frame) ---------- */
  --orbit-shadow-sx: 1;            /* contact shadow horizontal scale */
  --orbit-shadow-op: 0.6;          /* contact shadow opacity */
  --orbit-shadow-lift: 0px;        /* contact shadow vertical offset on grab */

  /* -- scroll-scrub progress (written by useScrollProgress) ------------- */
  --orbit-build: 0;                /* smoothed 0→1 */
  --orbit-build-raw: 0;            /* unsmoothed 0→1 */

  /* -- exploded part travel unit (responsive) -------------------------- */
  --orbit-explode-unit: 1.4px;     /* multiplied by per-part max in calc() */

  /* -- type ------------------------------------------------------------- */
  --orbit-font-display: var(--font-grotesk), "Space Grotesk", sans-serif;
  --orbit-font-body: "Inter", var(--font-noto-kr), system-ui, sans-serif;
  --orbit-font-ko: var(--font-noto-kr), "Inter", sans-serif;

  /* -- motion ----------------------------------------------------------- */
  --orbit-ease: cubic-bezier(0.22, 1, 0.36, 1);

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background: var(--orbit-floor);
  color: var(--orbit-frost);
  font-family: var(--orbit-font-body);
  font-size: clamp(15px, 0.35vw + 13.5px, 17px);
  line-height: 1.6;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Korean is first-class: it lands in Noto Sans KR through the stack, keeps
   its own line-breaking, and is never letter-spaced apart. */
.orbit-root :lang(ko) {
  font-family: var(--orbit-font-ko);
  word-break: keep-all;
  letter-spacing: -0.005em;
}

/* Ember selection, scoped to the entry root */
.orbit-root ::selection {
  background: var(--orbit-ember);
  color: var(--orbit-ink);
  text-shadow: none;
}

/* Keyboard focus: ember ring with a soft outer veil */
.orbit-root :focus-visible {
  outline: 2px solid var(--orbit-ember);
  outline-offset: 3px;
  border-radius: 4px;
  box-shadow: 0 0 0 6px rgba(255, 87, 34, 0.18);
}

.orbit-link {
  color: var(--orbit-frost);
  text-decoration: underline;
  text-decoration-color: rgba(255, 87, 34, 0.5);
  text-decoration-thickness: 1px;
  text-underline-offset: 4px;
}
.orbit-link:hover {
  text-decoration-color: var(--orbit-ember);
  text-shadow: 0 0 14px rgba(255, 87, 34, 0.4);
}

/* ==========================================================================
   01 · Hero — the seamless studio + the turntable
   ========================================================================== */

.orbit-hero {
  position: relative;
  isolation: isolate;
  min-height: 100vh;
  min-height: 100svh;
  overflow: hidden;
}

/* The seamless: floor rising into a cyclorama backdrop. Always painted —
   this is the no-JS view and the canvas understudy. */
.orbit-hero__seamless {
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(120% 80% at 50% 118%, var(--orbit-floor) 38%, transparent 62%),
    radial-gradient(100% 70% at 50% 0%, var(--orbit-rise) 0%, transparent 55%),
    linear-gradient(180deg, var(--orbit-rise) 0%, var(--orbit-floor) 60%, var(--orbit-ink) 100%);
}

/* Key-light pool — warm, stage-right-upper. The "lit" half of the studio. */
.orbit-hero__key {
  position: absolute;
  inset: -10%;
  background: radial-gradient(
    42% 38% at 72% 22%,
    rgba(255, 245, 230, 0.16),
    rgba(255, 245, 230, 0.04) 48%,
    transparent 70%
  );
  filter: blur(8px);
}

/* Rim-light pool — cool, stage-left-lower. Rakes the shadow side. */
.orbit-hero__rim {
  position: absolute;
  inset: -10%;
  background: radial-gradient(
    38% 42% at 20% 68%,
    rgba(184, 216, 255, 0.1),
    rgba(184, 216, 255, 0.02) 50%,
    transparent 72%
  );
  filter: blur(10px);
}

/* Corner vignette to seat text contrast and focus the eye on the product. */
.orbit-hero__vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    130% 110% at 60% 52%,
    transparent 50%,
    rgba(13, 13, 18, 0.55) 100%
  );
}

.orbit-hero__inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr;
  gap: clamp(24px, 4vh, 48px);
  align-items: center;
  min-height: 100vh;
  min-height: 100svh;
  max-width: 1280px;
  margin-inline: auto;
  padding: clamp(28px, 5vw, 64px);
}

@media (min-width: 920px) {
  .orbit-hero__inner {
    grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
    gap: clamp(32px, 4vw, 64px);
  }
}

