/* -- the stage ----------------------------------------------------------- */

.orbit-hero__stage {
  position: relative;
  width: 100%;
  min-height: clamp(320px, 52vh, 560px);
}

/* ==========================================================================
   The turntable stage — canvas + contact shadow + affordance ring
   ========================================================================== */

.orbit-stage {
  position: relative;
  width: 100%;
  height: clamp(320px, 52vh, 560px);
  touch-action: pan-y; /* allow vertical scroll, capture horizontal drag */
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
}
.orbit-stage:active {
  cursor: grabbing;
}

/* Affordance ring — 36 ticks at 10° each, purely decorative */
.orbit-stage__ring {
  position: absolute;
  inset: 8%;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0.5;
}
.orbit-stage__tick {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 1px;
  height: 49%;
  transform-origin: top center;
}
.orbit-stage__tick::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 1px;
  height: 8px;
  background: var(--orbit-hairline);
}
/* Every 3rd tick (30°) is slightly longer — a degree scale read */
.orbit-stage__tick:nth-child(3n)::before {
  height: 12px;
  background: var(--orbit-frost-dim);
  opacity: 0.6;
}

/* Contact shadow — elliptical, foreshortens with rotation. The vars are
   written imperatively from ProductTurntable's draw loop. */
.orbit-stage__shadow {
  position: absolute;
  left: 50%;
  bottom: 14%;
  width: 62%;
  height: 5%;
  transform: translateX(-50%) translatey(var(--orbit-shadow-lift)) scaleX(var(--orbit-shadow-sx));
  background: radial-gradient(
    50% 100% at 50% 50%,
    rgba(13, 13, 18, var(--orbit-shadow-op)) 0%,
    rgba(13, 13, 18, calc(var(--orbit-shadow-op) * 0.4)) 55%,
    transparent 80%
  );
  filter: blur(6px);
  pointer-events: none;
  will-change: transform, opacity;
}

.orbit-stage__canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none; /* the stage handles pointer events, not the canvas */
}

/* Drag hint + angle readout — studio instrument voice */
.orbit-stage__hint,
.orbit-stage__readout {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-grotesk), sans-serif;
  font-size: 0.66rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--orbit-frost-dim);
  pointer-events: none;
  transition: opacity 400ms var(--orbit-ease);
}
.orbit-stage__hint {
  bottom: 4%;
}
.orbit-stage__hint[data-active="false"] {
  opacity: 0;
}
.orbit-stage__readout {
  top: 4%;
  display: flex;
  align-items: baseline;
  gap: 0.6em;
}
.orbit-stage__readout-deg {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--orbit-ember);
  letter-spacing: 0.04em;
}
.orbit-stage__readout-ko {
  font-weight: 400;
  letter-spacing: 0.12em;
}

/* ==========================================================================
   Section headers — 0N · title · 한국어 · meta
   ========================================================================== */

.orbit-section__head {
  max-width: 1160px;
  margin: 0 auto clamp(2rem, 5vh, 3.2rem);
  padding-inline: clamp(20px, 5vw, 64px);
}
.orbit-section__no {
