/* ==========================================================================
   02 · The build — pinned, scrubbed, exploded
   ========================================================================== */

.orbit-build {
  position: relative;
  /* The pin runway: 220vh so there's scroll to scrub through. */
  height: 220vh;
  background: linear-gradient(180deg, var(--orbit-floor) 0%, var(--orbit-ink) 100%);
}
.orbit-build__sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 64px);
  overflow: hidden;
}
.orbit-build__head {
  text-align: center;
  margin-bottom: clamp(1.5rem, 4vh, 3rem);
}
/* The head inside the build is centered — reuse section classes but center */
.orbit-build .orbit-section__head {
  margin-inline: auto;
  text-align: center;
}

.orbit-build__diagram {
  position: relative;
  width: min(680px, 92vw);
  height: min(52vh, 460px);
  margin: 0 auto;
}

/* Rails — vertical hairlines connecting the parts, revealed by clip-path
   inset as the build progresses. Driven by --orbit-build (raw, unsmoothed). */
.orbit-build__rail {
  position: absolute;
  left: 50%;
  width: 1px;
  background: linear-gradient(
    180deg,
    transparent,
    var(--orbit-hairline) 18%,
    var(--orbit-hairline) 82%,
    transparent
  );
  transform: translateX(-50%);
  /* top/height set per-rail below */
  clip-path: inset(50% 0 50% 0);
  transition: none;
}
.orbit-build__rail--a { top: 18%; height: 64%; transform: translateX(calc(-50% - 38%)); }
.orbit-build__rail--b { top: 18%; height: 64%; transform: translateX(calc(-50% - 13%)); }
.orbit-build__rail--c { top: 18%; height: 64%; transform: translateX(calc(-50% + 13%)); }
.orbit-build__rail--d { top: 18%; height: 64%; transform: translateX(calc(-50% + 38%)); }

/* JS-gated rails draw themselves as build progresses */
.orbit-js .orbit-build__rail {
  clip-path: inset(calc((1 - var(--orbit-build-raw)) * 50%) 0 calc((1 - var(--orbit-build-raw)) * 50%) 0);
}

/* Part layers — absolutely positioned, stacked, each translating up by its
   own offset × build progress. */
.orbit-build__part {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 80%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4rem;
  transform: translate(-50%, -50%);
}
/* Per-part upward travel at progress=1 (in explode units). */
.orbit-build__part--counter  { transform: translate(-50%, calc(-50% - var(--orbit-build) * 150 * var(--orbit-explode-unit))); }
.orbit-build__part--laces    { transform: translate(-50%, calc(-50% - var(--orbit-build) * 95  * var(--orbit-explode-unit))); }
.orbit-build__part--upper    { transform: translate(-50%, calc(-50% - var(--orbit-build) * 40  * var(--orbit-explode-unit))); }
.orbit-build__part--midsole  { transform: translate(-50%, calc(-50% + var(--orbit-build) * 30  * var(--orbit-explode-unit))); }
.orbit-build__part--outsole  { transform: translate(-50%, calc(-50% + var(--orbit-build) * 95  * var(--orbit-explode-unit))); }

.orbit-build__part-art {
  width: 100%;
  filter: drop-shadow(0 8px 18px rgba(13, 13, 18, 0.5));
}
.orbit-build__svg {
  display: block;
  width: 100%;
  height: auto;
}

.orbit-build__part-label {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: center;
  gap: 0.3em 0.9em;
  margin-top: 0.3rem;
  opacity: calc(0.35 + 0.65 * var(--orbit-build));
}
.orbit-build__part-en {
  font-family: var(--font-grotesk), sans-serif;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--orbit-frost);
}
.orbit-build__part-ko {
  font-size: 0.74rem;
  color: var(--orbit-frost-dim);
}
.orbit-build__part-meta {
  font-size: 0.66rem;
  letter-spacing: 0.08em;
  color: var(--orbit-frost-dim);
  text-transform: uppercase;
  font-family: var(--font-grotesk), sans-serif;
}

/* Narrower explode travel on small screens so the diagram stays composed */
@media (max-width: 600px) {
  .orbit-root { --orbit-explode-unit: 0.9px; }
}

/* ==========================================================================
   03 · Colorway — clip-path wipe panels
   ========================================================================== */

.orbit-colorway {
  padding: clamp(80px, 12vh, 150px) clamp(20px, 5vw, 64px);
  background: var(--orbit-floor);
}
.orbit-colorway__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: clamp(14px, 2vw, 22px);
  max-width: 1160px;
  margin-inline: auto;
}
@media (min-width: 760px) {
  .orbit-colorway__grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.orbit-colorway__panel {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  padding: clamp(22px, 3vw, 32px);
  border: 1px solid var(--orbit-hairline);
  border-radius: 4px;
  background: linear-gradient(165deg, rgba(232, 238, 245, 0.04), rgba(232, 238, 245, 0) 40%), rgba(42, 42, 54, 0.5);
  text-align: left;
  cursor: pointer;
  font: inherit;
  color: var(--orbit-frost);
  transition: border-color 300ms var(--orbit-ease), transform 300ms var(--orbit-ease);
  clip-path: inset(0 0 0 0); /* visible by default (no-JS) */
}
.orbit-colorway__panel:hover {
  border-color: var(--orbit-frost-dim);
  transform: translateY(-2px);
}
.orbit-colorway__panel.is-selected {
  border-color: var(--orbit-ember);
  box-shadow: 0 0 0 1px var(--orbit-ember), 0 18px 44px rgba(13, 13, 18, 0.4);
}

/* JS-gated pre-wipe state. data-reveal-wipe picks the direction. */
.orbit-js .orbit-colorway__panel[data-reveal-wipe="0"] { clip-path: inset(0 0 0 100%); }
.orbit-js .orbit-colorway__panel[data-reveal-wipe="1"] { clip-path: inset(0 0 100% 0); }
.orbit-js .orbit-colorway__panel[data-reveal-wipe="2"] { clip-path: inset(0 100% 0 0); }

.orbit-js .orbit-colorway__panel.is-visible {
  clip-path: inset(0 0 0 0);
  transition:
    clip-path 640ms var(--orbit-ease) var(--orbit-wipe-delay, 0ms),
    border-color 300ms var(--orbit-ease),
    transform 300ms var(--orbit-ease);
}

/* Swatch */
.orbit-colorway__swatch {
  position: relative;
  width: 56px;
  height: 56px;
  margin-bottom: 0.4rem;
}
.orbit-colorway__swatch-dot {
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  box-shadow: inset 0 2px 6px rgba(255, 255, 255, 0.25), 0 4px 12px rgba(13, 13, 18, 0.5);
}
.orbit-colorway__swatch-ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1px solid var(--orbit-hairline);
}
.orbit-colorway__panel.is-selected .orbit-colorway__swatch-ring {
  border-color: var(--orbit-ember);
}

.orbit-colorway__name {
  display: flex;
  align-items: baseline;
  gap: 0.6em;
}
.orbit-colorway__name-en {
  font-family: var(--font-grotesk), sans-serif;
  font-size: 1.3rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.orbit-colorway__name-ko {
  font-size: 1rem;
  color: var(--orbit-frost-dim);
}
.orbit-colorway__blurb {
  margin: 0;
  font-size: 0.92rem;
  line-height: 1.5;
  color: var(--orbit-frost);
}
.orbit-colorway__blurb--ko {
  color: var(--orbit-frost-dim);
  font-size: 0.88rem;
}
.orbit-colorway__hex {
  margin-top: auto;
  padding-top: 0.8rem;
  font-family: var(--font-grotesk), sans-serif;
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  color: var(--orbit-frost-dim);
  border-top: 1px solid var(--orbit-hairline);
}

/* ==========================================================================
   04 · Footer — release notes
   ========================================================================== */

.orbit-footer {
  max-width: 1020px;
  margin-inline: auto;
  padding: clamp(64px, 10vh, 120px) clamp(20px, 5vw, 64px) clamp(90px, 13vh, 150px);
  border-top: 1px solid var(--orbit-hairline);
  background: var(--orbit-ink);
}
.orbit-footer__signoff {
  margin: 0 0 2.4rem;
  font-family: var(--font-grotesk), sans-serif;
  font-size: clamp(1.1rem, 2vw, 1.45rem);
  line-height: 1.5;
  color: var(--orbit-frost);
}
.orbit-footer__ko {
  display: block;
  margin-top: 0.4rem;
  color: var(--orbit-frost-dim);
}
.orbit-footer__spec {
  margin: 0 0 2.6rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 0.2rem 2rem;
}
.orbit-footer__spec div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.2rem 1rem;
  padding: 0.6rem 0;
  border-bottom: 1px dotted var(--orbit-hairline);
}
.orbit-footer__spec dt {
  flex: 0 0 5.5rem;
  font-family: var(--font-grotesk), sans-serif;
  font-size: 0.66rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--orbit-frost-dim);
  line-height: 2;
}
.orbit-footer__spec dd {
  flex: 1 1 14rem;
  margin: 0;
  font-size: 0.9rem;
}

.orbit-footer__calendar {
  margin: 0 0 2.4rem;
}
.orbit-footer__cal-title {
  margin: 0 0 1.2rem;
  font-family: var(--font-grotesk), sans-serif;
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  color: var(--orbit-frost);
}
.orbit-footer__cal-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.9rem;
}
.orbit-footer__cal-list li {
  display: grid;
  grid-template-columns: 5.5rem 1fr;
  gap: 0.3rem 1rem;
  align-items: baseline;
  padding-bottom: 0.9rem;
  border-bottom: 1px solid var(--orbit-hairline);
}
.orbit-footer__cal-date {
  font-family: var(--font-grotesk), sans-serif;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: var(--orbit-ember);
}
.orbit-footer__cal-name {
  font-size: 0.92rem;
  color: var(--orbit-frost);
}
.orbit-footer__cal-ko {
  color: var(--orbit-frost-dim);
  font-size: 0.86rem;
}

.orbit-footer__nav {
  margin: 0 0 2.2rem;
  font-size: 0.9rem;
}
.orbit-footer__copy {
  margin: 0;
  font-family: var(--font-grotesk), sans-serif;
  font-size: 0.9rem;
  color: var(--orbit-frost-dim);
}
.orbit-footer__copy .orbit-footer__ko {
  display: inline;
  margin: 0 0 0 0.4em;
}

/* ==========================================================================
   Scroll reveals — JS-gated pre-state, transform/opacity only
   ========================================================================== */

.orbit-js [data-reveal] {
  opacity: 0;
  transform: translateY(20px);
  transition:
    opacity 700ms var(--orbit-ease),
    transform 700ms var(--orbit-ease);
  will-change: opacity, transform;
}
.orbit-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ==========================================================================
   Reduced motion — the turntable is a re-posable still; everything readable
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  /* Reveals simply visible */
  .orbit-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  /* Clip-wipe panels simply visible */
  .orbit-js .orbit-colorway__panel,
  .orbit-js .orbit-colorway__panel[data-reveal-wipe="0"],
  .orbit-js .orbit-colorway__panel[data-reveal-wipe="1"],
  .orbit-js .orbit-colorway__panel[data-reveal-wipe="2"] {
    clip-path: inset(0 0 0 0);
    transition: none;
  }

  /* Drag hint stays visible (no inertia, so the affordance matters more) */
  .orbit-stage__hint[data-active="false"] {
    opacity: 1;
  }

  /* Hover transforms off — motion stays input-only */
  .orbit-colorway__panel:hover {
    transform: none;
  }
}
